    /// <summary>Gets the bottom and top glyph bounds using the same Unicode and WinAnsi aliases as advance widths.</summary>
    internal static bool TryGetVerticalBounds1000(PdfStandardFont font, char value, out int bottom, out int top) {
        short[]? bounds = font switch {
            PdfStandardFont.Helvetica => HelveticaPaintBounds,
            PdfStandardFont.HelveticaOblique => HelveticaObliquePaintBounds,
            PdfStandardFont.HelveticaBold => HelveticaBoldPaintBounds,
            PdfStandardFont.HelveticaBoldOblique => HelveticaBoldObliquePaintBounds,
            PdfStandardFont.TimesRoman => TimesRomanPaintBounds,
            PdfStandardFont.TimesItalic => TimesItalicPaintBounds,
            PdfStandardFont.TimesBold => TimesBoldPaintBounds,
            PdfStandardFont.TimesBoldItalic => TimesBoldItalicPaintBounds,
            PdfStandardFont.Courier => CourierPaintBounds,
            PdfStandardFont.CourierOblique => CourierObliquePaintBounds,
            PdfStandardFont.CourierBold => CourierBoldPaintBounds,
            PdfStandardFont.CourierBoldOblique => CourierBoldObliquePaintBounds,
            _ => null
        };
        bottom = top = 0;
        if (bounds == null) return false;
        // WinAnsiEncoding paints the space and hyphen glyphs for these characters.
        if (value == '\u00A0') value = ' ';
        else if (value == '\u00AD') value = '-';
        int index = System.Array.BinarySearch(Characters, value);
        if (index < 0) return false;
        bottom = bounds[index * 2];
        top = bounds[index * 2 + 1];
        // A zero box for a non-space glyph (notably Euro) has no qualified ink metadata.
        return value == ' ' || bottom != 0 || top != 0;
    }
